#include "../btree-cuda/GpuBTree.h"
#include <chrono>
#include <vector>
#include <algorithm>
#include <string>
struct StudyAllocator {
 uint32_t*pool;uint32_t*count;
 __device__ uint32_t allocate(){return atomicAdd(count,1u);}
 template<typename T> __device__ uint32_t*getAddressPtr(T address){return pool+address*32;}
};
static void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
struct Case {int n;std::vector<unsigned>k,v,q,wantq,wantpairs;unsigned*dk,*dv,*dq,*out,*root;StudyAllocator allocator;};
static std::vector<unsigned>canonical(std::vector<unsigned>&p,unsigned nodes){std::vector<std::pair<unsigned,unsigned>>rec;for(unsigned node=0;node<nodes;++node){unsigned b=node*32;if(!(p[b]&0x80000000u)){for(unsigned j=0;j<30;j+=2){unsigned k=p[b+j]&0x7fffffffu;if(k>=2)rec.emplace_back(k-2,(p[b+j+1]&0x7fffffffu)-2);}}}std::sort(rec.begin(),rec.end());std::vector<unsigned>out;for(auto kv:rec){out.push_back(kv.first);out.push_back(kv.second);}return out;}
int main(){constexpr unsigned words=1<<18;std::vector<Case>cases;std::vector<unsigned>prefix;for(int n:{256,4096}){Case c;c.n=n;for(int i=0;i<n;++i){unsigned k=(i*197+53)%n;c.k.push_back(k);c.v.push_back((uint64_t(k)*104729+97)%10000019+11);c.wantpairs.push_back(i);c.wantpairs.push_back((uint64_t(i)*104729+97)%10000019+11);}for(int i=0;i<2*n;++i){unsigned q=(i*313+19)%(2*n);c.q.push_back(q);c.wantq.push_back(q<unsigned(n)?(uint64_t(q)*104729+97)%10000019+11:0);}prefix.insert(prefix.end(),c.k.begin(),c.k.end());prefix.insert(prefix.end(),c.v.begin(),c.v.end());prefix.insert(prefix.end(),c.q.begin(),c.q.end());prefix.insert(prefix.end(),{unsigned(n),unsigned(2*n),words,256u});ck(cudaMalloc(&c.dk,n*4));ck(cudaMalloc(&c.dv,n*4));ck(cudaMalloc(&c.dq,2*n*4));ck(cudaMalloc(&c.out,2*n*4));ck(cudaMalloc(&c.root,4));ck(cudaMalloc(&c.allocator.pool,words*4));ck(cudaMalloc(&c.allocator.count,4));ck(cudaMemcpy(c.dk,c.k.data(),n*4,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.dv,c.v.data(),n*4,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.dq,c.q.data(),2*n*4,cudaMemcpyHostToDevice));cases.push_back(c);}auto run=[&](Case&c,std::vector<unsigned>&out,bool&ok){ck(cudaMemset(c.allocator.pool,0,words*4));ck(cudaMemset(c.allocator.count,0,4));ck(cudaMemset(c.root,0,4));ck(cudaMemset(c.out,0,2*c.n*4));GpuBTree::kernels::init_btree<<<1,32>>>(c.root,c.allocator);ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();GpuBTree::kernels::insert_keys<<<(c.n+255)/256,256>>>(c.root,c.dk,c.dv,unsigned(c.n),c.allocator);GpuBTree::kernels::search_b_tree<<<(2*c.n+255)/256,256>>>(c.root,c.dq,c.out,unsigned(2*c.n),c.allocator);ck(cudaDeviceSynchronize());double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();unsigned used;ck(cudaMemcpy(&used,c.allocator.count,4,cudaMemcpyDeviceToHost));if(used>words/32)exit(4);std::vector<unsigned>pool(used*32),q(2*c.n);ck(cudaMemcpy(pool.data(),c.allocator.pool,pool.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(q.data(),c.out,q.size()*4,cudaMemcpyDeviceToHost));auto pairs=canonical(pool,used);if(q!=c.wantq||pairs!=c.wantpairs)fprintf(stderr,"Tree witness N=%d nodes=%u query_ok=%d pairs=%zu expected=%zu first=%u\n",c.n,used,int(q==c.wantq),pairs.size(),c.wantpairs.size(),pairs.empty()?0:pairs[0]);ok&=q==c.wantq&&pairs==c.wantpairs;out=q;out.insert(out.end(),pairs.begin(),pairs.end());return t;};for(auto&c:cases){bool ok=true;std::vector<unsigned>out;run(c,out,ok);if(!ok)return 3;}for(int trial=1;trial<=5;++trial){auto out=prefix;bool ok=true;double elapsed=0;for(auto&c:cases){std::vector<unsigned>got;elapsed+=run(c,got,ok);out.insert(out.end(),got.begin(),got.end());}std::string path="trial_"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"timing_region\":\"sum_two_build_and_search_kernel_pairs\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",out.size(),path.c_str(),out.size());if(!ok)return 3;}for(auto&c:cases){cudaFree(c.dk);cudaFree(c.dv);cudaFree(c.dq);cudaFree(c.out);cudaFree(c.root);cudaFree(c.allocator.pool);cudaFree(c.allocator.count);}return 0;}
